def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    results = []

    index = 1
    for _ in range(t):
        x = int(data[index])
        result = 0
        while x > 0:
            if x >= 6:
                x -= 6
                result += 1
            elif x == 5:
                x -= 5
                result += 1
            elif x == 4:
                x -= 4
                result += 1
            elif x == 3:
                x -= 3
                result += 1
            elif x == 2:
                x -= 2
                result += 1
            else:
                break
        results.append(result)
        index += 1

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
